mapper.select:
select

from daily_train


    and train_id = #{trainId,jdbcType=BIGINT}


    and run_date = #{runDate,jdbcType=DATE}


order by run_date, train_id

select dt.id, dt.train_id, dt.run_date, dt.start_station_id, dt.end_station_id,
dt.start_time, dt.end_time, dt.status, dt.create_time, dt.update_time
from daily_train dt
join train_station ts_from on ts_from.train_id = dt.train_id and ts_from.station_id = #{fromStationId,jdbcType=BIGINT}
join train_station ts_to on ts_to.train_id = dt.train_id and ts_to.station_id = #{toStationId,jdbcType=BIGINT}
where dt.run_date = #{runDate,jdbcType=DATE}
  and dt.status = '1'
  and ts_from.station_index < ts_to.station_index
order by dt.start_time

mapper.update:
update daily_train
set status = #{status,jdbcType=CHAR}, update_time = now()
where id = #{id,jdbcType=BIGINT}
